mapper.select:
SELECT id, user_id, token, expires_at, device, logged_in_at, created_at
FROM refresh_token
WHERE token = #{token}

SELECT id, user_id, token, expires_at, device,
       COALESCE(logged_in_at, created_at) AS logged_in_at, created_at
FROM refresh_token
WHERE user_id = #{userId}
  AND expires_at > #{now}
ORDER BY created_at DESC

SELECT id, user_id, token, expires_at, device, logged_in_at, created_at
FROM refresh_token
WHERE id = #{id}

mapper.delete:
DELETE FROM refresh_token
WHERE user_id = #{userId}
  AND token <> #{keepToken}
